import "../../styles/index-base.css";
import "../../styles/components/tabs.css";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { cn } from "../../lib/cn";

export function Tabs({ className, ...props }: TabsPrimitive.Root.Props) {
  return <TabsPrimitive.Root className={cn("ix-tabs", className)} {...props} />;
}

export function TabsList({ className, activateOnFocus = true, ...props }: TabsPrimitive.List.Props) {
  return <TabsPrimitive.List className={cn("ix-tabs__list", className)} activateOnFocus={activateOnFocus} {...props} />;
}

export function TabsTrigger({ className, ...props }: TabsPrimitive.Tab.Props) {
  return <TabsPrimitive.Tab className={cn("ix-tabs__trigger", className)} {...props} />;
}

export function TabsContent({ className, ...props }: TabsPrimitive.Panel.Props) {
  return <TabsPrimitive.Panel className={cn("ix-tabs__panel", className)} {...props} />;
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-tabs { display: grid; gap: 16px; }

.ix-tabs__list { display: inline-flex; width: fit-content; height: 30px; align-items: center; gap: 2px; padding: 2px; border: 1px solid var(--ix-border-subtle); border-radius: 6px; background: var(--ix-subtle); }

.ix-tabs__trigger { position: relative; height: 24px; padding: 0 8px; border: 0; border-radius: 4px; outline: 0; background: transparent; color: var(--ix-ink-secondary); font-size: 12.5px; cursor: pointer; }

.ix-tabs__trigger:hover { color: var(--ix-fg-default); }

.ix-tabs__trigger[data-active] { background: var(--ix-control-surface); color: var(--ix-ink); box-shadow: var(--ix-shadow-control), 0 0 0 1px var(--ix-border-subtle); }

.ix-tabs__trigger[data-disabled] { opacity: 0.42; cursor: not-allowed; }

.ix-tabs__trigger:focus-visible { outline: 0; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ix-focus-control) 48%, transparent); }

.ix-tabs__trigger[data-active]:focus-visible { box-shadow: var(--ix-shadow-control), inset 0 0 0 1px color-mix(in oklch, var(--ix-focus-control) 54%, transparent); }

.ix-tabs__panel { outline: 0; }

@media (forced-colors: active) {
.ix-tabs__list { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.ix-tabs__trigger[data-active] { outline: 2px solid Highlight; outline-offset: -2px; }
}

:root[data-theme="dark"] .ix-tabs__trigger:hover { color: var(--ix-ink); }

.ix-tabs__trigger { transition: color var(--ix-hover-duration), background-color var(--ix-hover-duration), box-shadow var(--ix-hover-duration); }
}
